mapper.select:
SELECT au.id AS authorId, au.nickname AS authorName, au.avatar_url AS avatarUrl, au.total_articles AS totalArticles, au.hit_rate AS hitRate, au.recent_articles AS recentArticles, au.recent_hits AS recentHits, au.consecutive_hits AS consecutiveHits, au.on_sale_num AS onSaleNum, au.fans AS fans FROM author_user au WHERE au.status = 0 AND au.id IN ( SELECT DISTINCT aam.author_id FROM author_article_match aam WHERE aam.deleted=0
AND au.on_sale_num > 0
and aam.class_id = #{classId}
aam.class_id = -1
) ORDER BY au.recent_hits DESC LIMIT 100

